/**
 * A typed client of the Storefront API, for the front-ends and the other services.
 *
 * Nothing here is written by hand about the API: the types come from `schema.d.ts`, generated by
 * `openapi-typescript` from the committed `openapi.json` (`bun run client:generate`), which the
 * compiler generated from the controllers. `openapi-fetch` turns them into a `fetch` wrapper whose
 * paths, parameters, bodies and responses are checked by TypeScript:
 *
 * ```ts
 * const shop = createStorefrontClient({ baseUrl: 'https://shop.example.com', token })
 * const { data, error } = await shop.GET('/products/{id}', { params: { path: { id } } })
 * if (data) console.log(data.name, data.priceCents) // a ProductResponse
 * ```
 *
 * A server change that breaks the contract (a renamed route, a field removed from a response)
 * changes `openapi.json`, then `schema.d.ts`, and every caller that relied on it fails `typecheck`.
 *
 * The client does not depend on Znight: it is plain `fetch`. It lives in the application to be
 * type-checked against the generated file in the same build; publish it as its own package to share
 * it.
 */
import type { components, paths } from './schema.js'

import createClient, { type Client } from 'openapi-fetch'

/** The JSON Schemas of the document (`components.schemas`), as TypeScript types. */
export type Schemas = components['schemas']
export type ProductResponse = Schemas['ProductResponse']
export type CartResponse = Schemas['CartResponse']
export type Order = Schemas['Order']

/** The client: `GET`, `POST`, `PUT`... of every documented path. */
export type StorefrontClient = Client<paths>

/** Options of {@link createStorefrontClient}. */
export interface StorefrontClientOptions {
  /** Origin of the API (`https://shop.example.com`), with the HTTP prefix if any. */
  readonly baseUrl: string
  /** Token of a customer: carts and orders (`Authorization: Bearer <token>`). */
  readonly token?: string
  /** API key of the back office: products, images, export, statistics (`x-api-key`). */
  readonly apiKey?: string
  /** Another `fetch` (tests, instrumentation). Default: the global `fetch`. */
  readonly fetch?: (request: Request) => Promise<Response>
}

/** Creates a client sending the given credentials with every request. */
export function createStorefrontClient({ baseUrl, token, apiKey, fetch }: StorefrontClientOptions): StorefrontClient {
  const headers: Record<string, string> = {}
  if (token !== undefined) headers.authorization = `Bearer ${token}`
  if (apiKey !== undefined) headers['x-api-key'] = apiKey
  return createClient<paths>({ baseUrl, headers, ...(fetch === undefined ? {} : { fetch }) })
}

/**
 * Reads the order export (`GET /orders/export`, newline-delimited JSON) one order at a time, as it
 * arrives: request it with `parseAs: 'stream'`.
 *
 * ```ts
 * const { data } = await admin.GET('/orders/export', { parseAs: 'stream' })
 * for await (const order of readNdjson<Order>(data!)) console.log(order.id, order.totalCents)
 * ```
 */
export async function* readNdjson<T>(stream: ReadableStream<Uint8Array>): AsyncGenerator<T> {
  let buffered = ''
  for await (const text of stream.pipeThrough(new TextDecoderStream())) {
    buffered += text
    const lines = buffered.split('\n')
    buffered = lines.pop() ?? ''
    for (const line of lines) if (line.trim() !== '') yield JSON.parse(line) as T
  }
  if (buffered.trim() !== '') yield JSON.parse(buffered) as T
}
